cd /tmp/wt-main && python3 - <<'PYEOF'
import re,glob,yaml
bad=[]
for f in sorted(glob.glob('S0*/E*.md')):
    txt=open(f).read()
    parts=re.split(r"^---\s*$",txt,maxsplit=2,flags=re.M)
    meta=yaml.safe_load(parts[1])
    body=parts[2].strip()
    first=body.split('\n\n')[0].strip()
    summ=' '.join(str(meta.get('summary','')).split())
    if first!=summ: bad.append((f,'mismatch',first[:60],summ[:60]))
    for k in ('title','season','episode','status','summary'):
        if k not in meta: bad.append((f,'missing '+k,'',''))
    if not meta['title'].lower().startswith('the one with '): bad.append((f,'title style',meta['title'],''))
print("problems:",len(bad))
for b in bad[:20]: print(b)
