cd /tmp/wt-main && python3 - <<'PYEOF'
import re,glob,subprocess,collections
out_of_order=[]
dups=[]
for f in sorted(glob.glob('S0*/E*.md')):
    txt=open(f).read()
    entries=re.findall(r'^\*\*(\w+)\*\* \((\S+?)\)\n\nSource: (friend/\w+) @ ([0-9a-f]{40})',txt,re.M)
    shas=[e[3] for e in entries]
    if len(shas)!=len(set(shas)): dups.append((f,[s for s,c in collections.Counter(shas).items() if c>1]))
    ts=[e[1] for e in entries]
    if ts!=sorted(ts): out_of_order.append((f,[ (ts[i],ts[i+1]) for i in range(len(ts)-1) if ts[i]>ts[i+1]][:3]))
print("files with duplicate SHAs:",len(dups))
for d in dups[:10]: print(d)
print("files out of commit-time order:",len(out_of_order))
for o in out_of_order[:10]: print(o)
PYEOF
